import { Orm, SchemaBuilder } from '../../src'
import { eq } from 'drizzle-orm'
import { drizzle } from 'drizzle-orm/node-postgres'
import { Pool } from 'pg'
import { DocumentState, Position, TransactionLog } from '../fixtures/sharedKeyModels'

// A real drizzle instance so the statement is generated by drizzle itself: the join a relation
// compiles to is the only proof that it landed on the right column. The pool never connects.
// eslint-disable-next-line @typescript-eslint/no-explicit-any
let db: any
let preparedRows: unknown[] = []

beforeAll(() => {
    db = drizzle(new Pool({ host: 'localhost' }), { schema: SchemaBuilder.build() })
})

beforeEach(() => {
    jest.restoreAllMocks()
    preparedRows = []
    jest.spyOn(Orm, 'conn').mockReturnValue(db)
    jest.spyOn(db.session, 'prepareQuery').mockImplementation(() => ({ execute: async () => preparedRows }))
})

const sqlOf = (as: string): string =>
    Position.query().includeModel(Position, { as }).endInclude().toSQL().sql

describe('belongsTo with { targetKey }', () => {
    it('joins the foreign key to the named column instead of the primary key', () => {
        const sql = TransactionLog.query().includeModel(DocumentState).endInclude().toSQL().sql

        expect(sql).toContain('"transaction_logs_document"."guid" = "transaction_logs"."document_guid"')
        expect(sql).not.toContain('"transaction_logs_document"."id" = "transaction_logs"."document_guid"')
    })

    it('a required include builds the same condition inside the WHERE EXISTS', () => {
        const sql = TransactionLog.query().include({ model: DocumentState, required: true }).toSQL().sql

        expect(sql).toContain('exists (select 1 from "document_states" where "document_states"."guid" = "transaction_logs"."document_guid")')
    })
})

describe('hasMany with { sourceKey }', () => {
    it('points the foreign key back at the named column, not at the primary key', () => {
        const sql = DocumentState.query().includeModel(TransactionLog).endInclude().toSQL().sql

        expect(sql).toContain('"document_states_transactions"."document_guid" = "document_states"."guid"')
        expect(sql).not.toContain('= "document_states"."id"')
    })
})

describe('a self-reference on a plain column — every row sharing a field value', () => {
    it('belongsTo joins the shared column on both sides', () => {
        expect(sqlOf('genealogyPosition'))
            .toContain('"positions_genealogyPosition"."account_id" = "positions"."account_id"')
    })

    it('hasMany joins the shared column on both sides', () => {
        expect(sqlOf('treePositions'))
            .toContain('"positions_treePositions"."account_id" = "positions"."account_id"')
    })

    it('takes database column names as well as property keys', () => {
        expect(sqlOf('accountPositions'))
            .toContain('"positions_accountPositions"."account_id" = "positions"."account_id"')
    })

    it('hydrates the related rows into instances', async () => {
        preparedRows = [{
            id: 1,
            accountId: 7,
            title: 'root',
            treePositions: [{ id: 2, accountId: 7, title: 'second' }],
        }]
        const rows = await Position.query().includeModel(Position, { as: 'treePositions' }).endInclude().getAll()

        expect(rows[0]).toBeInstanceOf(Position)
        expect(rows[0].treePositions[0]).toBeInstanceOf(Position)
        expect(rows[0].treePositions[0].title).toBe('second')
    })

    it('a required include correlates the subquery with the outer row', () => {
        const sql = Position.query()
            .include({ model: Position, as: 'treePositions', required: true, where: { title: 'x' } })
            .toSQL().sql

        // the child side is aliased, or the condition would compare the subquery row with itself
        expect(sql).toContain('from "positions" "positions__exists"')
        expect(sql).toContain('"positions__exists"."account_id" = "positions"."account_id"')
        // and the include's own filter has to follow the alias, not stay on the parent
        expect(sql).toContain('"positions__exists"."title" = $2')
    })

    it('the recursive twin joins on the shared column too', () => {
        const sql = Position.recursiveQuery()
            .anchor(Position.query().where({ parentId: null }))
            .step(Position.query())
            .on((cte, step) => eq(cte.id, step.parentId))
            .includeModel(Position, { as: 'treePositions' })
            .endInclude()
            .toSQL().sql

        expect(sql).toContain('with recursive "positions__recursive" as (')
        expect(sql).toContain('"positions__recursive_treePositions"."account_id" = "positions__recursive"."account_id"')
    })
})

describe('a relation that names neither key is untouched', () => {
    it('belongsTo still joins the foreign key to the primary key', () => {
        expect(sqlOf('parent')).toContain('"positions_parent"."id" = "positions"."parent_id"')
        expect(sqlOf('parent')).not.toContain('"account_id" = "positions"."account_id"')
    })

    it('hasMany still joins the primary key to the foreign key', () => {
        expect(sqlOf('children')).toContain('"positions_children"."parent_id" = "positions"."id"')
    })

    it('compiles to exactly the statement it compiled to before', () => {
        expect(sqlOf('children')).toBe(
            'select "positions"."id", "positions"."account_id", "positions"."title", "positions"."parent_id", '
            + '"positions_children"."data" as "children" from "positions" "positions" left join lateral '
            + '(select coalesce(json_agg(json_build_array("positions_children"."id", "positions_children"."account_id", '
            + '"positions_children"."title", "positions_children"."parent_id")), \'[]\'::json) as "data" '
            + 'from "positions" "positions_children" where "positions_children"."parent_id" = "positions"."id") '
            + '"positions_children" on true',
        )
    })
})
